 async function resendInvitation(code){setBusy(true);setError('');try{const {data}=await supabase.auth.getSession();const response=await fetch('/api/patron-logins',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+data.session?.access_token},body:JSON.stringify({institution,rows:[{code}],resend:true})});const answer=await response.json();if(!response.ok)throw Error(answer.error);setAccountResults(old=>old.map(r=>r.code===code?answer.results[0]:r));}catch(e){setError(e.message);}finally{setBusy(false);}}
