 {drawer.kind==='copies'&&<><p className="drawer-description">{drawer.record.author} · {drawer.record.isbn}</p><div className="section-actions">{manage&&<><button className="button" onClick={()=>form('Edit bibliographic record','title',titleFields,drawer.record)}>Edit title</button><button className="button primary" onClick={()=>form('Add physical copy','copy',[field('accession','Accession number'),field('barcode','Barcode value'),field('shelf','Shelf','text',{required:false}),field('price','Price (INR)','number',{min:0,step:'0.01'})],{title_id:drawer.record.id,price:0})}><Plus size={16}/>Copy</button></>}{(circ||patron)&&<button className="button" onClick={()=>reserve(drawer.record.id)}>Place hold</button>}</div>{data.copies.filter(c=>c.title_id===drawer.record.id).map(c=><div className="copy-card" key={c.id}><div><strong>{c.accession}</strong>{badge(c.status)}<p>{c.barcode} · Shelf {c.shelf||'—'} · {money(c.price)}</p></div><div className="row-actions">{manage&&<button className="text-button" onClick={()=>sourceDetails(c.id)}>Source details</button>}<button className="text-button" onClick={()=>printLabel(c,drawer.record.title)}><Printer size={16}/>Label</button>{manage&&c.status!=='loaned'&&<button className="text-button" onClick={()=>form('Change copy status','copy_status',[field('status','Status','select',{options:['available','lost','damaged','withdrawn','missing']}),field('reason','Reason')],{id:c.id,status:c.status})}>Status</button>}</div></div>)}</>}
 {drawer.kind==='source'&&<>{drawer.records.length?drawer.records.map((r,n)=><section key={n}><p>{r.source} · {r.sheet} · row {r.row}</p><dl>{Object.entries(r.fields).map(([k,v])=><React.Fragment key={k}><dt>{k}</dt><dd>{String(v||'—')}</dd></React.Fragment>)}</dl></section>):<p>No spreadsheet source attached to this item.</p>}</>}
